using System.Reflection;

// Load all needed assemblies
var net10Dir = "/home/runner/.nuget/packages/microsoft.agents.ai/1.13.0/lib/net10.0/";
var absDir = "/home/runner/.nuget/packages/microsoft.agents.ai.abstractions/1.13.0/lib/net10.0/";
foreach (var dll in Directory.GetFiles(absDir, "*.dll")) Assembly.LoadFrom(dll);
var asm = Assembly.LoadFrom(Path.Combine(net10Dir, "Microsoft.Agents.AI.dll"));
var abs = Assembly.LoadFrom(Path.Combine(absDir, "Microsoft.Agents.AI.Abstractions.dll"));

var names = new[] { "ChatClientAgent", "ChatClientAgentOptions", "ChatClientAgentRunOptions", "AIAgentExtensions", "AIAgentBuilder", "IAIAgent" };
var types = asm.GetExportedTypes().Concat(abs.GetExportedTypes());
foreach (var t in types.Where(t => names.Any(n => t.Name == n)).OrderBy(t => t.FullName))
{
    Console.WriteLine($"\n=== {t.FullName} ===");
    if (t.BaseType != null && t.BaseType != typeof(object)) Console.WriteLine($"  Base: {t.BaseType}");
    foreach (var i in t.GetInterfaces().Take(5)) Console.WriteLine($"  Impl: {i}");
    foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  .ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName).Take(20))
        Console.WriteLine($"  {(m.IsStatic ? "static " : "")}{m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
}
