using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses the Brave Search API when a key is configured, otherwise falls back
/// to a DuckDuckGo instant-answer endpoint for zero-config demos.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _http;
    private readonly string? _braveApiKey;

    public WebSearchTool(HttpClient http, string? braveApiKey = null)
    {
        _http = http;
        _braveApiKey = braveApiKey;
    }

    [Description("Search the web for information on a given query. Returns a list of results with title, URL, and snippet.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrEmpty(_braveApiKey))
        {
            return await SearchWithBraveAsync(query, maxResults);
        }

        return await SearchWithDuckDuckGoAsync(query, maxResults);
    }

    private async Task<string> SearchWithBraveAsync(string query, int maxResults)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("X-Subscription-Token", _braveApiKey);
        request.Headers.Add("Accept", "application/json");

        var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var results = new List<SearchResult>();

        if (json.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var items))
        {
            foreach (var item in items.EnumerateArray().Take(maxResults))
            {
                results.Add(new SearchResult
                {
                    Title = item.GetProperty("title").GetString() ?? "",
                    Url = item.GetProperty("url").GetString() ?? "",
                    Snippet = item.TryGetProperty("description", out var desc)
                        ? desc.GetString() ?? ""
                        : "",
                });
            }
        }

        return FormatResults(query, results);
    }

    private async Task<string> SearchWithDuckDuckGoAsync(string query, int maxResults)
    {
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        var json = await _http.GetFromJsonAsync<JsonElement>(url);

        var results = new List<SearchResult>();

        if (json.TryGetProperty("AbstractText", out var abstractText) &&
            abstractText.GetString() is { Length: > 0 } text)
        {
            results.Add(new SearchResult
            {
                Title = json.TryGetProperty("Heading", out var h) ? h.GetString() ?? query : query,
                Url = json.TryGetProperty("AbstractURL", out var u) ? u.GetString() ?? "" : "",
                Snippet = text,
            });
        }

        if (json.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(maxResults - results.Count))
            {
                if (topic.TryGetProperty("Text", out var t) && t.GetString() is { Length: > 0 } topicText)
                {
                    results.Add(new SearchResult
                    {
                        Title = topicText.Length > 80 ? topicText[..80] + "..." : topicText,
                        Url = topic.TryGetProperty("FirstURL", out var fu) ? fu.GetString() ?? "" : "",
                        Snippet = topicText,
                    });
                }
            }
        }

        if (results.Count == 0)
        {
            return $"No results found for '{query}'. Try rephrasing the search query.";
        }

        return FormatResults(query, results);
    }

    private static string FormatResults(string query, List<SearchResult> results)
    {
        if (results.Count == 0)
            return $"No results found for '{query}'.";

        var lines = new List<string> { $"Search results for: \"{query}\"\n" };
        for (int i = 0; i < results.Count; i++)
        {
            var r = results[i];
            lines.Add($"[{i + 1}] {r.Title}");
            if (!string.IsNullOrEmpty(r.Url))
                lines.Add($"    URL: {r.Url}");
            lines.Add($"    {r.Snippet}");
            lines.Add("");
        }

        return string.Join('\n', lines);
    }

    private sealed class SearchResult
    {
        public string Title { get; set; } = "";
        public string Url { get; set; } = "";
        public string Snippet { get; set; } = "";
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities so the agent can record key findings
/// during research and later retrieve them for summarization.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    [Description("Save a research note with a topic tag and content. Use this to record key findings from search results.")]
    public string SaveNote(
        [Description("A short topic tag for the note (e.g. 'definition', 'history', 'key-people')")] string topic,
        [Description("The content of the note — a fact, quote, or insight worth remembering")] string content,
        [Description("The source URL or reference, if available")] string? source = null)
    {
        var note = new Note
        {
            Id = _notes.Count + 1,
            Topic = topic,
            Content = content,
            Source = source,
            Timestamp = DateTime.UtcNow,
        };

        _notes.Add(note);
        return $"Note #{note.Id} saved under topic '{topic}'.";
    }

    [Description("Retrieve all saved notes, optionally filtered by topic tag.")]
    public string GetNotes(
        [Description("Optional topic tag to filter notes by. Leave empty to get all notes.")] string? topic = null)
    {
        var filtered = string.IsNullOrEmpty(topic)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrEmpty(topic)
                ? "No notes saved yet."
                : $"No notes found for topic '{topic}'.";
        }

        var lines = new List<string> { $"--- Research Notes ({filtered.Count}) ---\n" };
        foreach (var note in filtered)
        {
            lines.Add($"[#{note.Id}] Topic: {note.Topic}");
            lines.Add($"  {note.Content}");
            if (!string.IsNullOrEmpty(note.Source))
                lines.Add($"  Source: {note.Source}");
            lines.Add("");
        }

        return string.Join('\n', lines);
    }

    public sealed class Note
    {
        public int Id { get; set; }
        public string Topic { get; set; } = "";
        public string Content { get; set; } = "";
        public string? Source { get; set; }
        public DateTime Timestamp { get; set; }
    }
}

