+/// </summary>
+public sealed class NoteTool
+{
+    private readonly List<Note> _notes = [];
+
+    public IReadOnlyList<Note> Notes => _notes;
+
+    [Description("Save a research note with a topic tag and content. Use this to record key findings from search results.")]
+    public string SaveNote(
+        [Description("A short topic tag for the note (e.g. 'definition', 'history', 'key-people')")] string topic,
+        [Description("The content of the note — a fact, quote, or insight worth remembering")] string content,
+        [Description("The source URL or reference, if available")] string? source = null)
+    {
+        var note = new Note
+        {
+            Id = _notes.Count + 1,
+            Topic = topic,
+            Content = content,
+            Source = source,
+            Timestamp = DateTime.UtcNow,
+        };
+
+        _notes.Add(note);
+        return $"Note #{note.Id} saved under topic '{topic}'.";
+    }
+
+    [Description("Retrieve all saved notes, optionally filtered by topic tag.")]
+    public string GetNotes(
+        [Description("Optional topic tag to filter notes by. Leave empty to get all notes.")] string? topic = null)
+    {
+        var filtered = string.IsNullOrEmpty(topic)
+            ? _notes
+            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();
+
+        if (filtered.Count == 0)
+        {
+            return string.IsNullOrEmpty(topic)
+                ? "No notes saved yet."
+                : $"No notes found for topic '{topic}'.";
+        }
+
+        var lines = new List<string> { $"--- Research Notes ({filtered.Count}) ---\n" };
+        foreach (var note in filtered)
+        {
+            lines.Add($"[#{note.Id}] Topic: {note.Topic}");
+            lines.Add($"  {note.Content}");
+            if (!string.IsNullOrEmpty(note.Source))
+                lines.Add($"  Source: {note.Source}");
+            lines.Add("");
+        }
+
+        return string.Join('\n', lines);
+    }
+
+    public sealed class Note
+    {
+        public int Id { get; set; }
+        public string Topic { get; set; } = "";
+        public string Content { get; set; } = "";
+        public string? Source { get; set; }
+        public DateTime Timestamp { get; set; }
+    }
+}
