using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// --- Configuration ---
var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OpenAI API key via AI:ApiKey in config, or the OPENAI_API_KEY environment variable.");
var braveApiKey = builder.Configuration["Search:BraveApiKey"]
    ?? Environment.GetEnvironmentVariable("BRAVE_API_KEY");

// --- Services ---
builder.Services.AddHttpClient();

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton(sp =>
    new WebSearchTool(sp.GetRequiredService<IHttpClientFactory>().CreateClient("search"), braveApiKey));
builder.Services.AddSingleton<NoteTool>();

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var searchTool = sp.GetRequiredService<WebSearchTool>();
    var noteTool = sp.GetRequiredService<NoteTool>();

    var tools = new AITool[]
    {
        AIFunctionFactory.Create(searchTool.SearchWebAsync),
        AIFunctionFactory.Create(noteTool.SaveNote),
        AIFunctionFactory.Create(noteTool.GetNotes),
    };

    return new ChatClientAgent(chatClient, instructions: ResearchInstructions.System, name: "Researcher",
        description: "An AI agent that researches topics by searching the web and taking notes.",
        tools: tools,
        loggerFactory: sp.GetRequiredService<ILoggerFactory>());
});

var host = builder.Build();

// --- Interactive loop ---
var agent = host.Services.GetRequiredService<ChatClientAgent>();
var noteTool2 = host.Services.GetRequiredService<NoteTool>();

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent               ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input)) continue;
    if (input.Equals("quit", StringComparison.OrdinalIgnoreCase) ||
        input.Equals("exit", StringComparison.OrdinalIgnoreCase)) break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"Researching \"{input}\"...\n");
    Console.ResetColor();

    try
    {
        var session = await agent.CreateSessionAsync();
        var prompt = $"Research the following topic thoroughly: {input}\n\n" +
                     "Search the web for information, save important findings as notes, " +
                     "then retrieve your notes and produce a comprehensive summary.";

        await foreach (var update in agent.RunStreamingAsync(prompt, session))
        {
            if (update.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }

        Console.WriteLine();

        // Show collected notes
        if (noteTool2.Notes.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"\n📝 {noteTool2.Notes.Count} note(s) were saved during research.");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

