1. using Microsoft.Extensions.AI;
2. using Microsoft.Extensions.DependencyInjection;
3. using Microsoft.Extensions.Hosting;
4. using Microsoft.Extensions.Logging;
5. using Microsoft.Agents.AI;
6. using OpenAI;
7. using ResearchAgent.Tools;
8. 
9. var builder = Host.CreateApplicationBuilder(args);
10. 
11. // --- Configuration ---
12. var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";
13. var apiKey = builder.Configuration["AI:ApiKey"]
14.     ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
15.     ?? throw new InvalidOperationException(
16.         "Set the OpenAI API key via AI:ApiKey in config, or the OPENAI_API_KEY environment variable.");
17. var braveApiKey = builder.Configuration["Search:BraveApiKey"]
18.     ?? Environment.GetEnvironmentVariable("BRAVE_API_KEY");
19. 
20. // --- Services ---
21. builder.Services.AddHttpClient();
22. 
23. var openAiClient = new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient();
24. builder.Services.AddChatClient(sp =>
25.     new ChatClientBuilder(openAiClient)
26.         .UseFunctionInvocation()
27.         .Build(sp));
28. 
29. 
30. builder.Services.AddSingleton(sp =>
31.     new WebSearchTool(sp.GetRequiredService<IHttpClientFactory>().CreateClient("search"), braveApiKey));
32. builder.Services.AddSingleton<NoteTool>();
33. 
34. builder.Services.AddSingleton(sp =>
35. {
36.     var chatClient = sp.GetRequiredService<IChatClient>();
37.     var searchTool = sp.GetRequiredService<WebSearchTool>();
38.     var noteTool = sp.GetRequiredService<NoteTool>();
39. 
40.     var tools = new AITool[]
41.     {
42.         AIFunctionFactory.Create(searchTool.SearchWebAsync),
43.         AIFunctionFactory.Create(noteTool.SaveNote),
44.         AIFunctionFactory.Create(noteTool.GetNotes),
45.     };
46. 
47.     return new ChatClientAgent(chatClient, instructions: ResearchInstructions.System, name: "Researcher",
48.         description: "An AI agent that researches topics by searching the web and taking notes.",
49.         tools: tools,
50.         loggerFactory: sp.GetRequiredService<ILoggerFactory>());
51. });
52. 
53. var host = builder.Build();
54. 
55. // --- Interactive loop ---
56. var agent = host.Services.GetRequiredService<ChatClientAgent>();
57. var noteTool2 = host.Services.GetRequiredService<NoteTool>();
58. 
59. Console.WriteLine("╔══════════════════════════════════════════╗");
60. Console.WriteLine("║       🔍 AI Research Agent               ║");
61. Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
62. Console.WriteLine("╚══════════════════════════════════════════╝");
63. Console.WriteLine();
64. 
65. while (true)
66. {
67.     Console.ForegroundColor = ConsoleColor.Cyan;
68.     Console.Write("Research topic> ");
69.     Console.ResetColor();
70. 
71.     var input = Console.ReadLine()?.Trim();
72.     if (string.IsNullOrEmpty(input)) continue;
73.     if (input.Equals("quit", StringComparison.OrdinalIgnoreCase) ||
74.         input.Equals("exit", StringComparison.OrdinalIgnoreCase)) break;
75. 
76.     Console.WriteLine();
77.     Console.ForegroundColor = ConsoleColor.DarkGray;
78.     Console.WriteLine($"Researching \"{input}\"...\n");
79.     Console.ResetColor();
80. 
81.     try
82.     {
83.         var session = await agent.CreateSessionAsync();
84.         var prompt = $"Research the following topic thoroughly: {input}\n\n" +
85.                      "Search the web for information, save important findings as notes, " +
86.                      "then retrieve your notes and produce a comprehensive summary.";
87. 
88.         await foreach (var update in agent.RunStreamingAsync(prompt, session))
89.         {
90.             if (update.Text is { Length: > 0 } text)
91.             {
92.                 Console.Write(text);
93.             }
94.         }
95. 
96.         Console.WriteLine();
97. 
98.         if (noteTool2.Notes.Count > 0)
99.         {
100.             Console.ForegroundColor = ConsoleColor.DarkYellow;
101.             Console.WriteLine($"\n📝 {noteTool2.Notes.Count} note(s) were saved during research.");
102.             Console.ResetColor();
103.         }
104.     }
105.     catch (Exception ex)
106.     {
107.         Console.ForegroundColor = ConsoleColor.Red;
108.         Console.WriteLine($"Error: {ex.Message}");
109.         Console.ResetColor();
110.     }
111. 
112.     Console.WriteLine();
113. }
114. 
115. Console.WriteLine("Goodbye!");
116. 
117. internal static class ResearchInstructions
118. {
119.     public const string System = """
120.         You are a thorough research assistant. Your goal is to investigate a topic
121.         by searching the web and collecting key findings in notes.
122. 
123.         Follow this workflow:
124.         1. Break the topic into 2-3 specific search queries.
125.         2. Search the web for each query using the SearchWebAsync tool.
126.         3. For each search, save the most important facts using the SaveNote tool
127.            with a descriptive topic tag and the source URL.
128.         4. After gathering information, retrieve all your notes with GetNotes.
129.         5. Synthesize a well-structured summary with:
130.            - An overview paragraph
131.            - Key findings organized by subtopic
132.            - Sources cited at the end
133. 
134.         Be factual and cite your sources. If search results are limited,
135.         acknowledge gaps in the available information.
136.         """;
137. }
138.

